=head2 Google::Cloud::Networkconnectivity::V1::Hub::SpokeSummary

Summarizes information about the spokes associated with a hub.
The summary includes a count of spokes according to type
and according to state. If any spokes are inactive,
the summary also lists the reasons they are inactive,
including a count for each reason.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->spoke_type_counts() >> / C<< $msg->spoke_type_counts($value) >>

Type: C<Message> (L<Google::Cloud::Networkconnectivity::V1::Hub::SpokeSummary::SpokeTypeCount>)

Output only. Counts the number of spokes of each type that are
associated with a specific hub.

=item * C<< $msg->spoke_state_counts() >> / C<< $msg->spoke_state_counts($value) >>

Type: C<Message> (L<Google::Cloud::Networkconnectivity::V1::Hub::SpokeSummary::SpokeStateCount>)

Output only. Counts the number of spokes that are in each state
and associated with a given hub.

=item * C<< $msg->spoke_state_reason_counts() >> / C<< $msg->spoke_state_reason_counts($value) >>

Type: C<Message> (L<Google::Cloud::Networkconnectivity::V1::Hub::SpokeSummary::SpokeStateReasonCount>)

Output only. Counts the number of spokes that are inactive for each
possible reason and associated with a given hub.

=back

